    private static SAV8LA Open(byte[] data)=>new(data.ToArray());
    private static void Reject(Action a){try{a();throw new Exception("Invalid Trainer8a edit accepted");}catch(ArgumentException){}}
    private static byte[] Fixture(int revision,int gender)
