        var original=Open(LegendsPokedexTests.Fixture(revision));uint[] uints=[SaveBlockAccessor8LA.KMoney,SaveBlockAccessor8LA.KMeritCurrent,SaveBlockAccessor8LA.KMeritEarnedTotal,SaveBlockAccessor8LA.KExpeditionTeamRank,SaveBlockAccessor8LA.KSatchelUpgrades,SaveBlockAccessor8LA.KGameLanguage];var blocks=original.AllBlocks.Select(b=>uints.Contains(b.Key)?SwshBlockFixtureTests.Typed(b.Key,b.Data.ToArray(),SCTypeCode.UInt32):b.Clone()).ToArray();var s=Open(SwishCrypto.Encrypt(blocks));s.OT="TEST";s.TID16=12345;s.SID16=54321;s.Gender=(byte)gender;s.Language=9;s.Money=12345;s.PlayedHours=123;s.PlayedMinutes=12;s.PlayedSeconds=34;s.AdventureStart.Timestamp=new(2020,1,2,3,4,5);s.LastSaved.Timestamp=new(2021,2,3,4,5,6);s.Coordinates.Data.Fill(0xA7);s.Coordinates.M="old_map";s.Coordinates.X=1.25f;s.Coordinates.Z=-2.5f;s.Coordinates.Y=3.75f;s.Coordinates.RX=.2f;s.Coordinates.RZ=0;s.Coordinates.RY=.3f;s.Coordinates.RW=1;foreach(uint key in uints.Skip(1).Take(4))s.SetValue(key,4000000000u);return s.Write().ToArray();
    }
    private static byte[] Compare(byte[] data,Tr8aEdit edit,Action<SAV8LA> change,out string[] ignored)
    {
        var original=data.ToArray();var s=Open(data);change(s);var hash=Br4Editing.Hash(data);var preview=Trainer8aEditing.Prepare(Open(data),edit with{SourceHash=hash},hash,data.Length,out ignored);var output=Trainer8aEditing.Prepare(Open(data),edit with{SourceHash=hash,TargetHash=Br4Editing.Hash(preview)},hash,data.Length,out _);Check(output.SequenceEqual(s.Write().ToArray()),"Trainer8a independent complete encrypted-file parity: "+edit.Action);Check(data.SequenceEqual(original)&&SwishCrypto.GetIsHashValid(output),"Trainer8a immutable original and regenerated hash");return output;
    }
    public static void Run()
    {
        for(int revision=0;revision<2;revision++)for(int gender=0;gender<2;gender++)
        {
            var data=Fixture(revision,gender);var c=Trainer8aEditing.Read(Open(data),Br4Editing.Hash(data));Check(c.Fields.Length==13&&c.Position.CanEdit&&c.Fields.Single(f=>f.Key=="rank").Value=="4000000000"&&c.Fields.Single(f=>f.Key=="rank").Max=="999999999","Trainer8a source fields retain raw over-limit values");
            Compare(data,new("patch",null,[new("name","NEW"),new("money","9999999"),new("language","1"),new("gender",gender==0?"1":"0")]),s=>{StringConverter8.SetString(s.Blocks.GetBlock(0xF25C070E).Data.Slice(0x20,26),"NEW",12,StringConverterOption.ClearZero);BinaryPrimitives.WriteUInt32LittleEndian(s.Blocks.GetBlock(0x3279D927).Data,9999999);s.Blocks.GetBlock(0xF25C070E).Data[0x17]=1;s.Blocks.GetBlock(0xF25C070E).Data[0x15]=(byte)(1-gender);BinaryPrimitives.WriteUInt32LittleEndian(s.Blocks.GetBlock(SaveBlockAccessor8LA.KGameLanguage).Data,1);},out _);
            var allZero=Open(data);allZero.Coordinates.X=allZero.Coordinates.Y=allZero.Coordinates.Z=allZero.Coordinates.RZ=0;allZero.Coordinates.RW=1;var zeroData=allZero.Write().ToArray();Compare(zeroData,new("position",null,[new("map","new_map")],UiLanguage:"en"),_=>{},out var mapIgnored);Check(mapIgnored.SequenceEqual(new[]{"map"}),"Trainer8a zero-loaded map-only omission");
            Compare(data,new("position",null,[new("map","new_map")],UiLanguage:"en"),s=>{var raw=s.Blocks.GetBlock(0x267DD9DA).Data;raw.Slice(8,72).Clear();System.Text.Encoding.ASCII.GetBytes("new_map").CopyTo(raw[8..]);BinaryPrimitives.WriteSingleLittleEndian(raw[0x60..],0);BinaryPrimitives.WriteSingleLittleEndian(raw[0x68..],0);},out var loadedIgnored);Check(loadedIgnored.Length==0,"Trainer8a nonzero-loaded map change saves");
            Compare(data,new("position",null,[new("map","地图"),new("x","12.5"),new("rotation","90")],UiLanguage:"en"),s=>{var raw=s.Blocks.GetBlock(0x267DD9DA).Data;raw.Slice(8,72).Clear();raw[8]=raw[9]=(byte)'?';BinaryPrimitives.WriteSingleLittleEndian(raw[0x50..],12.5f);BinaryPrimitives.WriteSingleLittleEndian(raw[0x60..],0);BinaryPrimitives.WriteSingleLittleEndian(raw[0x64..],(float)Math.Sin(Math.PI/4));BinaryPrimitives.WriteSingleLittleEndian(raw[0x68..],0);BinaryPrimitives.WriteSingleLittleEndian(raw[0x6C..],(float)Math.Cos(Math.PI/4));},out _);
            Compare(zeroData,new("position",null,[new("x",""),new("rotation","invalid")],UiLanguage:"en"),_=>{},out var ignored);Check(ignored.Length==2,"Trainer8a invalid coordinates preserve source values");
            Compare(data,new("patch",null,[new("started","2030-05-06T07:08:09"),new("saved","2031-06-07T08:09:10")]),s=>{ulong seconds=(ulong)(new DateTime(2030,5,6,7,8,9)-new DateTime(1970,1,1)).TotalSeconds;BinaryPrimitives.WriteUInt64LittleEndian(s.Blocks.GetBlock(0xAEE903A2).Data,seconds);var raw=s.Blocks.GetBlock(0x1B1E3D8B).Data;uint packed=(uint)(2031-1900)|5u<<12|7u<<16|8u<<21|9u<<26;BinaryPrimitives.WriteUInt32LittleEndian(raw,packed);if(raw.Length>4)raw[4]=10;},out _);
            Compare(data,new("resave",null),s=>{foreach(uint key in new[]{SaveBlockAccessor8LA.KMeritCurrent,SaveBlockAccessor8LA.KMeritEarnedTotal,SaveBlockAccessor8LA.KExpeditionTeamRank,SaveBlockAccessor8LA.KSatchelUpgrades})BinaryPrimitives.WriteUInt32LittleEndian(s.Blocks.GetBlock(key).Data,999999999);var position=s.Blocks.GetBlock(0x267DD9DA).Data;BinaryPrimitives.WriteSingleLittleEndian(position[0x60..],0);BinaryPrimitives.WriteSingleLittleEndian(position[0x64..],0);BinaryPrimitives.WriteSingleLittleEndian(position[0x68..],0);BinaryPrimitives.WriteSingleLittleEndian(position[0x6C..],1);},out _);
            Compare(data,new("ids",null,[new("tid","123456"),new("sid","1234")]),s=>BinaryPrimitives.WriteUInt32LittleEndian(s.Blocks.GetBlock(0xF25C070E).Data[0x10..],1234123456),out _);
            Compare(data,new("trash",null,Trash:new("text",Text:"友")),s=>{var raw=s.Blocks.GetBlock(0xF25C070E).Data.Slice(0x20,26);byte[] encoded=new byte[26];int n=StringConverter8.SetString(encoded,"友",12,StringConverterOption.ClearZero);encoded.AsSpan(0,n).CopyTo(raw);},out _);
            foreach(var edit in new[]{new Tr8aEdit("patch",c.SourceHash,[new("rank","1000000000")]),new("position",c.SourceHash,[new("map",new string('a',49))],UiLanguage:"en"),new("patch",c.SourceHash,[new("saved","1999-01-01T00:00:00")]),new("invalid",c.SourceHash)})Reject(()=>Trainer8aEditing.Prepare(Open(data),edit,c.SourceHash,data.Length,out _));Reject(()=>Trainer8aEditing.Prepare(Open(data),new("resave",new string('0',64)),c.SourceHash,data.Length,out _));var invalid=Open(data);invalid.Coordinates.X=float.NaN;Check(!Trainer8aEditing.Read(invalid,c.SourceHash).Position.CanEdit,"Trainer8a invalid coordinate group disabled");Reject(()=>Trainer8aEditing.Prepare(invalid,new("position",c.SourceHash,[new("x","0")]),c.SourceHash,data.Length,out _));
            Console.WriteLine($"PASS Trainer8a revision {revision}/gender {gender}: typed synthetic blocks, 13 source fields/raw clamp, runtime language, IDs/name bytes, map-only omission/ASCII/numeric-triggered quaternion, epochs, independent full-file parity and atomic rejection/original; not SaveService or real-save acceptance");
        }
    }
